code_example:
char *path = "/bin/echo";
char *const args[] = {"echo", "Hello", "World", NULL};
/* envp array must be explicitly terminated by NULL */
char *const envs[] = {"MYVAR=42", NULL};

/* execve replaces the current process image.
   It only returns upon failure (-1). */
int ret = execve(path, args, envs);

/* Failure handling */
if (ret == -1) {
    /* errno is set */
    perror("execve");
}
